const EXERCISES=[
['chest','מקבילים בנטייה קדימה','Forward Lean Dips','מורכב','משקל גוף','הטה את הגוף קלות קדימה, שמור כתפיים רחוקות מהאוזניים ורד רק בטווח נשלט.'],['chest','לחיצת חזה בשיפוע חיובי','Incline Dumbbell Press','מורכב','דאמבלים','הצמד שכמות לספסל, שמור שורש כף יד ניטרלי והורד מרפקים בזווית בטוחה.'],['chest','לחיצת חזה שטוחה','Flat Barbell Bench Press','מורכב','מוט','צור בסיס יציב ברגליים, אסוף שכמות והורד את המוט אל מרכז החזה בשליטה.'],['chest','פרפר בכבלים','Cable Fly','בידוד','כבלים','שמור כפיפה קלה וקבועה במרפק והפגש ידיים בלי לאבד מתח בחזה.'],['chest','שכיבות סמיכה רחבות','Wide Push-Ups','מורכב','משקל גוף','שמור גוף בקו אחד, בטן אסופה ואל תיתן למרפקים להיפתח לחלוטין לצדדים.'],['chest','לחיצה בשיפוע שלילי','Decline Chest Press','מורכב','מכונה','קבע את הגב, דחוף בקו החזה התחתון והימנע מנעילת מרפקים אגרסיבית.'],['chest','פרפר במכונה','Pec Deck Fly','בידוד','מכונה','כוון מושב כך שהמרפקים בגובה החזה וסגור בתנועה חלקה ללא תנופה.'],['chest','לחיצת חזה אחיזה צרה','Close Grip Bench Press','מורכב','מוט','שמור מרפקים קרובים לגוף ואחיזה מעט צרה מרוחב כתפיים.'],
['triceps','פשיטת מרפקים בחבל','Rope Pushdown','בידוד','כבלים','קבע מרפקים לצדי הגוף ופצל את החבל בתחתית בלי להזיז כתפיים.'],['triceps','לחיצה צרפתית','Skull Crushers','בידוד','מוט W','הזז רק את המרפקים והורד את המוט מאחורי קו המצח בטווח נוח.'],['triceps','שכיבות סמיכה יהלום','Diamond Push-Ups','מורכב','משקל גוף','שמור ליבה חזקה ומרפקים קרובים; עבוד על ברכיים אם הטכניקה נשברת.'],['triceps','מקבילים צמודים','Triceps Dips','מורכב','משקל גוף','שמור גו זקוף וטווח כתף נוח; אל תשקע בתחתית.'],['triceps','פשיטה מעבר לראש בדאמבל','Overhead Dumbbell Extension','בידוד','דאמבל','שמור צלעות אסופות ומרפקים פונים קדימה.'],['triceps','פשיטה מעבר לראש בכבל','Cable Overhead Extension','בידוד','כבלים','עמוד יציב, הארך מרפקים עד הסוף בלי לקשת את הגב.'],['triceps','קיקבאק בדאמבל','Dumbbell Kickback','בידוד','דאמבלים','קבע זרוע עליונה מקבילה לרצפה והימנע מתנופה.'],['triceps','לחיצת חזה במכונה אחיזה צרה','Machine Close Press','מורכב','מכונה','בחר עומס המאפשר שליטה ואל תרים כתפיים.'],
['back','מתח אחיזה רחבה','Wide Grip Pull-Up','מורכב','משקל גוף','התחל מהורדת שכמות, משוך חזה למוט והימנע מתנופה.'],['back','מתח אחיזה צרה','Close Grip Pull-Up','מורכב','משקל גוף','שמור חזה פתוח ומשוך מרפקים לכיוון הצלעות.'],['back','פולי עליון','Lat Pulldown','מורכב','כבלים','משוך אל החזה העליון בלי להישען לאחור יתר על המידה.'],['back','חתירה במשקולת בודדת','One-Arm Dumbbell Row','מורכב','דאמבל','שמור גב ניטרלי ומשוך מרפק אל האגן, לא אל הכתף.'],['back','חתירה בפולי תחתון','Seated Cable Row','מורכב','כבלים','הובל עם המרפקים ושמור גו יציב ללא נדנוד.'],['back','פולאובר בכבל','Straight Arm Pulldown','בידוד','כבלים','שמור מרפקים כמעט ישרים ודחוף את המוט אל הירכיים.'],['back','חתירה במוט T','T-Bar Row','מורכב','מוט','קבע ליבה, שמור גב ניטרלי והימנע ממשיכה בצוואר.'],['back','חתירה במכונה נתמכת חזה','Chest Supported Row','מורכב','מכונה','השאר חזה צמוד לכרית וכווץ שכמות בסוף התנועה.'],
['biceps','כפיפת מרפקים במוט W','EZ-Bar Curl','מורכב','מוט W','שמור מרפקים מתחת לכתפיים והימנע מהטיית הגב לאחור.'],['biceps','פטישים','Hammer Curls','בידוד','דאמבלים','שמור כפות ידיים זו מול זו ותנועה איטית בירידה.'],['biceps','כפיפה בפריצ׳ר','Preacher Curl','בידוד','מכונה','אל תנעל את המרפק בתחתית; שמור זרוע על הכרית.'],['biceps','כפיפה בשיפוע','Incline Dumbbell Curl','בידוד','דאמבלים','השאר כתפיים לאחור והארך את הזרוע בשליטה.'],['biceps','כפיפה מרוכזת','Concentration Curl','בידוד','דאמבל','קבע מרפק בירך והימנע מסיבוב הגו.'],['biceps','כפיפה בפולי תחתון','Low Cable Curl','בידוד','כבלים','שמור מתח רציף ומפרק כף יד ישר.'],['biceps','כפיפת ספיידר','Spider Curl','בידוד','דאמבלים','השען חזה על הספסל ואל תזיז את הזרוע העליונה.'],['biceps','כפיפה הפוכה','Reverse Curl','בידוד','מוט W','אחוז מלמעלה, שמור שורש כף יד בקו האמה.'],
['shoulders','לחיצת כתפיים בדאמבלים','Dumbbell Shoulder Press','מורכב','דאמבלים','אסוף צלעות, שמור אמות אנכיות ודחוף מעל הראש ללא כאב.'],['shoulders','לחיצת כתפיים במוט','Barbell Overhead Press','מורכב','מוט','כווץ ישבן וליבה, העבר את הראש קדימה רק אחרי מעבר המוט.'],['shoulders','הרחקת זרועות לצדדים','Dumbbell Lateral Raise','בידוד','דאמבלים','הרם בקו השכמה עד גובה כתף, בלי למשוך בטרפז.'],['shoulders','הרחקה לצדדים בפולי','Cable Lateral Raise','בידוד','כבלים','שמור מתח קבוע והובל עם המרפק בתנועה מבוקרת.'],['shoulders','פרפר הפוך','Reverse Pec Deck','בידוד','מכונה','פתח זרועות בלי לקשת גב וכווץ כתף אחורית.'],['shoulders','חתירה לסנטר','Upright Row','מורכב','מוט W','משוך רק עד טווח נוח ושמור מרפקים לא גבוהים מדי.'],['shoulders','הנפה קדמית','Front Raise','בידוד','דאמבלים','הרם עד גובה כתף ללא תנופה מהגב.'],['shoulders','פייס פול','Face Pull','בידוד','כבלים','משוך אל המצח עם מרפקים פתוחים וסובב כתפיים החוצה.'],
['core','כפיפות בטן על בוסו','Bosu Crunch','בידוד','משקל גוף','הניע את עמוד השדרה בהדרגה ואל תמשוך בצוואר.'],['core','הרמות רגליים בתלייה','Hanging Leg Raise','מורכב','משקל גוף','הטה אגן לאחור והימנע מתנופה.'],['core','פלאנק סטטי','Static Plank','מורכב','משקל גוף','כווץ ישבן ובטן ושמור אוזן־כתף־אגן בקו אחד.'],['core','פלאנק דינמי','Dynamic Plank','מורכב','משקל גוף','מנע סיבוב באגן ועבור בין האמות לכפות הידיים בשליטה.'],['core','רוטציות רוסיות','Russian Twists','מורכב','משקל גוף','סובב בית חזה ולא רק ידיים; שמור גב ארוך.'],['core','גלגלת בטן','Ab Wheel Rollout','מורכב','גלגל מהכתפיים ושמור אגן אסוף כדי למנוע קשת בגב.'],['core','דד באג','Dead Bug','מורכב','משקל גוף','הצמד גב תחתון לרצפה והארך גפיים לאט.'],['core','פאלוף פרס','Pallof Press','מורכב','כבלים','התנגד לסיבוב ושמור אגן וכתפיים ישרים.']
].map((x,i)=>({id:i+1,muscle:x[0],he:x[1],en:x[2],type:x[3],equipment:x[4],cue:x[5]}));
const MUSCLE_HE={chest:'חזה',triceps:'יד אחורית',back:'גב',biceps:'יד קדמית',shoulders:'כתפיים',core:'בטן וליבה'};
const MUSCLE_POS={chest:'0% 0%',triceps:'50% 0%',back:'100% 0%',biceps:'0% 100%',shoulders:'50% 100%',core:'100% 100%'};
function tilePos(e){let n=(e.id-1)%8,col=n%4,row=Math.floor(n/4);return`${col*33.333}% ${row*100}%`}
function visualStyle(e){return`--atlas:url('assets/${e.muscle}-atlas.png');--pos:${tilePos(e)}`}
const SPLITS=[{title:'חזה + יד אחורית',main:'chest',secondary:'triceps',accent:'var(--lime)'},{title:'גב + יד קדמית',main:'back',secondary:'biceps',accent:'var(--cyan)'},{title:'כתפיים + בטן',main:'shoulders',secondary:'core',accent:'var(--orange)'}];
const STORE_KEY='pulsefit-state-v1';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let state=loadState(),timer=null,elapsedTimer=null,rest={left:0,total:0};
function loadState(){try{return JSON.parse(localStorage.getItem(STORE_KEY))||defaultState()}catch{return defaultState()}}
function defaultState(){return{week:null,active:null,history:[],startedAt:null}}
function save(){localStorage.setItem(STORE_KEY,JSON.stringify(state))}
function shuffle(a){return [...a].sort(()=>Math.random()-.5)}
function rx(ex){return ex.type==='מורכב'?{sets:4,reps:ex.equipment==='משקל גוף'?'עד כשל':'8–10'}:{sets:3,reps:'10–15'}}
function generateDay(split){let main=EXERCISES.filter(x=>x.muscle===split.main),sec=EXERCISES.filter(x=>x.muscle===split.secondary);let first=shuffle(main.filter(x=>x.type==='מורכב'))[0];let remaining=shuffle(main.filter(x=>x.id!==first.id)).slice(0,3);return[first,...remaining,...shuffle(sec).slice(0,3)].map(e=>({...e,...rx(e)}))}
function generateWeek(){state.week=SPLITS.map((s,i)=>({id:i+1,title:s.title,exercises:generateDay(s)}));save();renderWeek();toast('השבוע החדש מוכן ⚡')}
function renderWeek(){if(!state.week)generateWeek();$('#weekPlan').innerHTML=state.week.map((d,i)=>`<article class="day-card ${i===0?'open':''}" data-day="${i}"><div class="day-summary"><div class="day-no">0${i+1}</div><div class="day-main"><small>אימון ${i+1}</small><h3>${d.title}</h3><span class="day-count">${d.exercises.length} תרגילים · כ־55 דק׳</span></div><span class="chev">⌄</span></div><div class="day-detail">${d.exercises.map((e,j)=>`<div class="plan-exercise"><span class="drag-handle">⋮⋮</span><div><b>${e.he}</b><small>${e.sets} סטים × ${e.reps}</small></div><div class="plan-actions"><button class="mini-btn move" data-dir="${j?'up':'down'}" data-i="${i}" data-j="${j}" aria-label="שנה סדר">${j?'↑':'↓'}</button><button class="mini-btn swap" data-i="${i}" data-j="${j}" aria-label="החלף תרגיל">↻</button></div></div>`).join('')}<button class="start-workout" data-start="${i}">התחל אימון</button></div></article>`).join('');bindWeek()}
function bindWeek(){$$('.day-summary').forEach(x=>x.onclick=()=>x.parentElement.classList.toggle('open'));$$('.swap').forEach(b=>b.onclick=e=>{e.stopPropagation();swapExercise(+b.dataset.i,+b.dataset.j)});$$('.move').forEach(b=>b.onclick=e=>{e.stopPropagation();moveExercise(+b.dataset.i,+b.dataset.j,b.dataset.dir)});$$('[data-start]').forEach(b=>b.onclick=()=>startWorkout(+b.dataset.start))}
function swapExercise(di,ei){let old=state.week[di].exercises[ei],pool=EXERCISES.filter(x=>x.muscle===old.muscle&&!state.week[di].exercises.some(y=>y.id===x.id));if(!pool.length)return toast('אין חלופה נוספת בקבוצה');let next=shuffle(pool)[0];state.week[di].exercises[ei]={...next,...rx(next)};save();renderWeek();toast('התרגיל הוחלף')}
function moveExercise(di,ei,dir){let arr=state.week[di].exercises,target=dir==='up'?ei-1:ei+1;if(target<0||target>=arr.length)return;[arr[ei],arr[target]]=[arr[target],arr[ei]];save();renderWeek()}
function startWorkout(i){let day=state.week[i];state.active={day:i,title:day.title,exercises:day.exercises.map(e=>({...e,logs:Array.from({length:e.sets},()=>({weight:'',reps:typeof e.reps==='number'?e.reps:'',done:false}))}))};state.startedAt=Date.now();save();renderActive();go('workout');startElapsed();toast('האימון התחיל — קדימה!')}
function renderActive(){let a=state.active;$('#workoutEmpty').hidden=!!a;$('#activeWorkout').hidden=!a;$('#activeDot').classList.toggle('show',!!a);if(!a)return;$('#activeDayLabel').textContent=`אימון ${a.day+1}`;$('#activeTitle').textContent=a.title;$('#activeExercises').innerHTML=a.exercises.map((e,i)=>`<article class="workout-exercise ${e.logs.every(s=>s.done)?'done':''}"><div class="workout-exercise-head"><div><h3>${e.he}</h3><p>${e.en} · ${e.reps} חזרות</p></div><span class="exercise-index">${i+1}</span></div><div class="set-head"><span>סט</span><span>משקל</span><span>חזרות</span><span>בוצע</span></div>${e.logs.map((s,j)=>`<div class="set-row"><label>${j+1}</label><input inputmode="decimal" value="${s.weight}" placeholder="ק״ג" data-field="weight" data-e="${i}" data-s="${j}"><input inputmode="numeric" value="${s.reps}" placeholder="חזרות" data-field="reps" data-e="${i}" data-s="${j}"><button class="set-check ${s.done?'checked':''}" data-check data-e="${i}" data-s="${j}">${s.done?'✓':'○'}</button></div>`).join('')}</article>`).join('');$$('#activeExercises input').forEach(inp=>inp.onchange=()=>{state.active.exercises[+inp.dataset.e].logs[+inp.dataset.s][inp.dataset.field]=inp.value;save()});$$('[data-check]').forEach(b=>b.onclick=()=>toggleSet(+b.dataset.e,+b.dataset.s));updateProgress()}
function toggleSet(e,s){let row=state.active.exercises[e].logs[s];row.done=!row.done;save();renderActive();if(row.done)startRest(state.active.exercises[e].type==='מורכב'?90:60)}
function updateProgress(){if(!state.active)return;let sets=state.active.exercises.flatMap(e=>e.logs),done=sets.filter(x=>x.done).length;$('#workoutProgress').style.width=`${done/sets.length*100}%`}
function startElapsed(){clearInterval(elapsedTimer);elapsedTimer=setInterval(()=>{if(!state.startedAt)return;let sec=Math.floor((Date.now()-state.startedAt)/1000);$('#elapsedTime').textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`},1000)}
function startRest(seconds){clearInterval(timer);rest={left:seconds,total:seconds};$('#timerDock').hidden=false;drawTimer();timer=setInterval(()=>{rest.left--;drawTimer();if(rest.left<=0){clearInterval(timer);navigator.vibrate?.([100,70,100]);try{let ac=new (window.AudioContext||window.webkitAudioContext)(),o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);o.frequency.value=740;g.gain.value=.08;o.start();o.stop(ac.currentTime+.2)}catch{}toast('המנוחה הסתיימה — לסט הבא!');setTimeout(()=>$('#timerDock').hidden=true,1800)}},1000)}
function drawTimer(){$('#timerValue').textContent=rest.left;$('#timerArc').style.strokeDashoffset=119.4*(1-rest.left/rest.total)}
function finishWorkout(){if(!state.active)return;let duration=Math.max(1,Math.round((Date.now()-state.startedAt)/60000)),logs=state.active.exercises.flatMap(e=>e.logs),done=logs.filter(x=>x.done),volume=done.reduce((n,s)=>n+(+s.weight||0)*(+s.reps||0),0),entry={date:new Date().toISOString(),title:state.active.title,duration,volume,sets:done.length};state.history.unshift(entry);state.active=null;state.startedAt=null;save();clearInterval(elapsedTimer);$('#finishDuration').textContent=duration;$('#finishVolume').textContent=Math.round(volume).toLocaleString('he-IL');$('#finishSets').textContent=done.length;let text=encodeURIComponent(`אימון כוח|${duration}|${Math.round(duration*6.5)}`);$('#healthShortcut').href=`shortcuts://run-shortcut?name=Log%20Workout&input=text&text=${text}`;showModal('finishModal');confetti();renderActive();renderStats()}
function renderLibrary(filter='all',term=''){let muscles=['all',...Object.keys(MUSCLE_HE)];$('#muscleFilters').innerHTML=muscles.map(m=>`<button class="chip ${m===filter?'active':''}" data-muscle="${m}">${m==='all'?'הכול':MUSCLE_HE[m]}</button>`).join('');let list=EXERCISES.filter(e=>(filter==='all'||e.muscle===filter)&&(`${e.he} ${e.en} ${e.equipment}`.toLowerCase().includes(term.toLowerCase())));$('#exerciseGrid').innerHTML=list.map(e=>`<button class="exercise-card" data-exercise="${e.id}"><div class="exercise-visual" style="${visualStyle(e)}"></div><div class="info"><h3>${e.he}</h3><p>${e.en}</p><div class="tags"><span class="tag">${e.type}</span><span class="tag">${e.equipment}</span></div></div></button>`).join('');$$('[data-muscle]').forEach(b=>b.onclick=()=>renderLibrary(b.dataset.muscle,$('#exerciseSearch').value));$$('[data-exercise]').forEach(b=>b.onclick=()=>openExercise(+b.dataset.exercise))}
function openExercise(id){let e=EXERCISES.find(x=>x.id===id),v=$('#modalVisual');v.style.setProperty('--atlas',`url('assets/${e.muscle}-atlas.png')`);v.style.setProperty('--pos',tilePos(e));$('#modalMeta').textContent=`${MUSCLE_HE[e.muscle]} · ${e.type} · ${e.equipment}`;$('#modalName').textContent=e.he;$('#modalEnglish').textContent=e.en;$('#modalCue').textContent=e.cue;showModal('exerciseModal')}
function calcStreak(){if(!state.history.length)return 0;let weeks=new Set(state.history.map(h=>{let d=new Date(h.date),first=new Date(d.getFullYear(),0,1),w=Math.ceil((((d-first)/864e5)+first.getDay()+1)/7);return `${d.getFullYear()}-${w}`}));return weeks.size}
function renderStats(){let total=state.history.reduce((n,h)=>n+h.volume,0),streak=calcStreak();$('#streakValue').textContent=streak;$('#statsStreak').textContent=streak;$('#totalWorkouts').textContent=state.history.length;$('#totalVolume').textContent=total>999?`${(total/1000).toFixed(1)}k`:Math.round(total);$('#historyList').innerHTML=state.history.length?state.history.slice(0,8).map(h=>`<article class="history-item"><div class="history-icon">✓</div><div class="history-info"><b>${h.title}</b><small>${new Date(h.date).toLocaleDateString('he-IL')} · ${h.duration} דקות</small></div><div class="history-volume"><b>${Math.round(h.volume).toLocaleString('he-IL')}</b><small>ק״ג נפח</small></div></article>`).join(''):`<div class="empty-state" style="padding:30px"><p>האימון הראשון שלך יופיע כאן.</p></div>`;drawChart()}
function drawChart(){let c=$('#volumeChart'),ctx=c.getContext('2d'),dpr=devicePixelRatio||1,w=c.clientWidth,h=180;c.width=w*dpr;c.height=h*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);let vals=[0,0,0,0],now=new Date;state.history.forEach(x=>{let diff=Math.floor((now-new Date(x.date))/6048e5);if(diff<4)vals[3-diff]+=x.volume});let max=Math.max(...vals,100),pad=26;ctx.strokeStyle='#253235';ctx.lineWidth=1;for(let i=0;i<4;i++){let y=pad+i*(h-2*pad)/3;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}let pts=vals.map((v,i)=>[i*(w-24)/3+12,h-pad-(v/max)*(h-2*pad)]);let grad=ctx.createLinearGradient(0,0,w,0);grad.addColorStop(0,'#43e6db');grad.addColorStop(1,'#b7ff3c');ctx.strokeStyle=grad;ctx.lineWidth=3;ctx.lineJoin='round';ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke();ctx.lineTo(pts[3][0],h-pad);ctx.lineTo(pts[0][0],h-pad);ctx.closePath();let fill=ctx.createLinearGradient(0,pad,0,h);fill.addColorStop(0,'#b7ff3c38');fill.addColorStop(1,'#b7ff3c00');ctx.fillStyle=fill;ctx.fill();pts.forEach(p=>{ctx.beginPath();ctx.arc(...p,4,0,Math.PI*2);ctx.fillStyle='#b7ff3c';ctx.fill()})}
function confetti(){let c=$('#confettiCanvas'),ctx=c.getContext('2d');c.width=innerWidth;c.height=innerHeight;let bits=Array.from({length:90},()=>({x:Math.random()*c.width,y:-20-Math.random()*c.height/2,v:2+Math.random()*5,r:Math.random()*6+3,a:Math.random()*6.2,c:['#b7ff3c','#43e6db','#ff8a3d','#fff'][Math.floor(Math.random()*4)]}));let n=0;(function frame(){ctx.clearRect(0,0,c.width,c.height);bits.forEach(b=>{b.y+=b.v;b.x+=Math.sin(b.y/30);b.a+=.07;ctx.save();ctx.translate(b.x,b.y);ctx.rotate(b.a);ctx.fillStyle=b.c;ctx.fillRect(-b.r,-b.r/2,b.r*2,b.r);ctx.restore()});if(n++<180)requestAnimationFrame(frame)})()}
function go(name){$$('.view').forEach(v=>v.classList.toggle('active',v.dataset.view===name));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.target===name));if(name==='stats')renderStats();scrollTo({top:0,behavior:'smooth'})}
function showModal(id){let m=$('#'+id);m.classList.add('show');m.setAttribute('aria-hidden','false')}
function hideModal(id){let m=$('#'+id);m.classList.remove('show');m.setAttribute('aria-hidden','true')}
let toastTimer;function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
function noArgs(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('הפעולה אינה מקבלת פרמטרים')}
function registerWebMCP(){let mc=document.modelContext;if(!mc?.registerTool)return;try{mc.registerTool({name:'generate_weekly_workout_plan',title:'בניית תוכנית שבועית',description:'יוצר תוכנית כוח חדשה לשלושה אימונים ומציג אותה באפליקציה.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){noArgs(input);generateWeek();go('planner');return{created:true,days:3}}});mc.registerTool({name:'read_workout_summary',title:'קריאת סיכום אימונים',description:'מחזיר סיכום קצר של היסטוריית האימונים המקומית.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){noArgs(input);return{workouts:state.history.length,totalVolume:Math.round(state.history.reduce((n,h)=>n+h.volume,0)),streakWeeks:calcStreak()}}})}catch{}}
function init(){let d=new Date;$('#todayLabel').textContent=d.toLocaleDateString('he-IL',{weekday:'long',day:'numeric',month:'long'});renderWeek();renderActive();renderLibrary();renderStats();if(state.active)startElapsed();$$('.nav-item').forEach(b=>b.onclick=()=>go(b.dataset.target));$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$('#generateBtn').onclick=generateWeek;$('#rerollAll').onclick=generateWeek;$('#finishWorkout').onclick=finishWorkout;$('#timerSkip').onclick=$('#timerDismiss').onclick=()=>{clearInterval(timer);$('#timerDock').hidden=true};$('#searchToggle').onclick=()=>$('#searchWrap').classList.toggle('show');$('#exerciseSearch').oninput=e=>{let current=$('.chip.active')?.dataset.muscle||'all';renderLibrary(current,e.target.value)};$$('[data-close]').forEach(b=>b.onclick=()=>hideModal(b.dataset.close));$('#finishClose').onclick=()=>{hideModal('finishModal');go('stats')};$$('.modal').forEach(m=>m.onclick=e=>{if(e.target===m&&m.id!=='finishModal')hideModal(m.id)});addEventListener('resize',()=>{if($('#statsView').classList.contains('active'))drawChart()});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js');registerWebMCP()}
init();
